def transform(grid):
    g = np.array(grid)
    out = g.copy()
    H, W = g.shape
    board = np.isin(g, [4, 5, 7])
    ys, xs = np.nonzero(board)
    by0, by1, bx0, bx1 = ys.min(), ys.max(), xs.min(), xs.max()
    fives = components(g == 5)
    sevens = components(g == 7)
    out[g == 5] = 4
    emit(out, "Clear every 5 strip on the board rim back to the board colour 4.")
    for blk in sevens:
        bs = set(blk)
        n = 0
        for f in fives:
            if any((y + dy, x + dx) in bs for (y, x) in f
                   for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1))):
                n += len(f)
        if n == 0:
            continue
        y0, x0, y1, x1 = bbox(blk)
        if y0 == by0:
            layers = [[(y, x) for x in range(x0, x1 + 1)] for y in range(y0, y1 + 1)]
        elif y1 == by1:
            layers = [[(y, x) for x in range(x0, x1 + 1)] for y in range(y1, y0 - 1, -1)]
        elif x0 == bx0:
            layers = [[(y, x) for y in range(y0, y1 + 1)] for x in range(x0, x1 + 1)]
        else:
            layers = [[(y, x) for y in range(y0, y1 + 1)] for x in range(x1, x0 - 1, -1)]
        left = n
        for layer in layers:
            if left <= 0:
                break
            for (y, x) in layer:
                out[y, x] = 5
            left -= len(layer)
        emit(out, f"Pour the {n} touching 5 cells into the 7 block at {(y0, x0)}, filling layers from the board edge inward.")
    emit(out, "Final grid.")
    return out
